from typing import Callable, List

Predicate = Callable[[int], bool]

def predicate_limit_bit(P: Predicate, block: int) -> bool:
    """Cell 0 of the predicate limit rule at a given block boundary."""
    return P(block)

def boundary_trace(P: Predicate, length: int) -> List[bool]:
    """Recover oracle bits P(0)..P(length-1) via boundary read-out."""
    return [predicate_limit_bit(P, k) for k in range(length)]

if __name__ == "__main__":
    P: Predicate = lambda n: n % 2 == 0
    trace = boundary_trace(P, 8)
    print("boundary trace:", trace)
    print("matches oracle:", trace == [P(k) for k in range(8)])

