function OMEGA_SQUARED_TABLE(step, limit, initial, K, N):
    history[0] <- [ step^n(initial) for n in 0..N ]
    for k in 1..K-1:
        seed <- limit(history[k-1])          # limit layer: read full prev history
        history[k] <- [ step^n(seed) for n in 0..N ]   # successor layer
    return history

# Boundary read-out of the scheduled oracle run:
function BOUNDARY_TRACE(history, m):
    return [ history[k+1][0](0) for k in 0..m-1 ]

function PREDICATE_LIMIT(P, block):
    return tape t where t(0) = P(block), t(i) = false for i > 0

function ENCODE(P, m):
    # boundary bits that the scheduled run will exhibit
    return [ PREDICATE_LIMIT(P, k)(0) for k in 0..m-1 ]

function DECODE(boundary_bits):
    # inverse of ENCODE; recovers the oracle prefix
    return boundary_bits

