from typing import Callable, List

Predicate = Callable[[int], bool]

def predicate_limit(P: Predicate, block: int) -> Callable[[int], bool]:
    return lambda i: (P(block) if i == 0 else False)

def encode(P: Predicate, m: int) -> List[bool]:
    """Boundary bits of the scheduled Rule 110 run for oracle P."""
    return [predicate_limit(P, k)(0) for k in range(m)]

def decode(boundary_bits: List[bool]) -> List[bool]:
    """Recover the oracle prefix from boundary read-outs (identity map)."""
    return list(boundary_bits)

if __name__ == "__main__":
    P: Predicate = lambda n: (n * n) % 5 == 1
    bits = encode(P, 10)
    assert decode(bits) == [P(k) for k in range(10)]
    print("round-trip ok:", bits)

