from typing import Callable

Predicate = Callable[[int], bool]

def diagonal(E: Callable[[int], Predicate]) -> Predicate:
    """Predicate not equal to any E(n): flips the n-th bit of E(n)."""
    return lambda n: not E(n)(n)

def verify(E: Callable[[int], Predicate], D: Predicate, m: int) -> bool:
    return all(D(n) != E(n)(n) for n in range(m))

if __name__ == "__main__":
    E: Callable[[int], Predicate] = lambda n: (lambda k, nn=n: (k >> nn) & 1 == 1)
    D = diagonal(E)
    print("diagonal escapes enumeration:", verify(E, D, 16))
